INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(4501, 'Deuteronomy 1:32', 'Deuteronomy', 1, 32, '&nbsp;خو د دې هرې خبرې باوجود، تاسو بيا هم په مالِک خُدائ يقين نۀ کولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4502, 'Deuteronomy 1:33', 'Deuteronomy', 1, 33, '&nbsp;اګر کۀ هغه همېشه ستاسو نه مخکښې روان وو چې ستاسو دپاره د خېمو لګولو ځائ ولټوى. ستاسو د لارښودنې دپاره هغه به ستاسو په مخکښې د شپې د اور په ستن کښې او د ورځې د وريځې په ستن کښې روان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4503, 'Deuteronomy 1:34', 'Deuteronomy', 1, 34, '&nbsp;مالِک خُدائ ستاسو شکايتونه واورېدل او په غصه شو، نو هغۀ دا قسم وخوړو او وې فرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4504, 'Deuteronomy 1:35', 'Deuteronomy', 1, 35, '&nbsp;ستاسو د دې بدعمله نسل نه يو کس به هم هغه زرخېز مُلک ته ورننه نۀ وځى چې د کوم د ورکولو لوظ ما ستاسو پلار نيکۀ سره کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4505, 'Deuteronomy 1:36', 'Deuteronomy', 1, 36, '&nbsp;صِرف د يفُنه زوئ کالب به ورننوځى. ځکه چې هغه په ما ايمان لرى او زۀ به هغۀ او د هغۀ اولاد له هغه مُلک ورکړم د کوم چې هغۀ معلومات حاصل کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4506, 'Deuteronomy 1:37', 'Deuteronomy', 1, 37, '&nbsp;ځکه چې ستاسو په وجه مالِک خُدائ ما ته هم غصه شو او وې فرمائيل چې اے موسىٰ، تۀ به هم هغه مُلک ته ورننه نۀ وځې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4507, 'Deuteronomy 1:38', 'Deuteronomy', 1, 38, '&nbsp;خو د خپل مددګار، د نون زوئ يشوَع، حوصله مضبوطه کړه. هغه به اِسرائيليان بوځى چې هغه مُلک قبضه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4508, 'Deuteronomy 1:39', 'Deuteronomy', 1, 39, '&nbsp;بيا مالِک خُدائ مونږ ټولو ته وفرمائيل چې، ستاسو واړۀ بچى به هغه مُلک ته ورننه وځى، چې هغوئ په ښۀ او بد نۀ پوهيږى. هغه ماشومان چې تاسو ووئيل چې ستاسو دشمنان به يې ونيسى. زۀ به هغوئ له هغه مُلک ورکوم او هغوئ به يې قبضه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4509, 'Deuteronomy 1:40', 'Deuteronomy', 1, 40, '&nbsp;خو اوس تاسو واپس وګرځئ او واپس بيابان ته په هغه لار لاړ شئ کومه چې بحرِقُلزم ته ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4510, 'Deuteronomy 1:41', 'Deuteronomy', 1, 41, '&nbsp;تاسو ووئيل، موسىٰ، مونږ د مالِک خُدائ خِلاف ګناه کړې ده. خو اوس به مونږ حمله وکړُو، چې څنګه مالِک خُدائ زمونږ خُدائ پاک مونږ ته حُکم کړے دے. بيا ستاسو هر يو کس د جنګ دپاره تيار شو، خيال مو دا وو چې د غرونو مُلک قبضه کول به آسان کار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4511, 'Deuteronomy 1:42', 'Deuteronomy', 1, 42, '&nbsp;خو مالِک خُدائ ما ته وفرمائيل چې هغوئ له خبردارے ورکړه چې حمله ونۀ کړى، ځکه چې زۀ به د هغوئ مل نۀ يم او دشمن به هغوئ له شکست ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4512, 'Deuteronomy 1:43', 'Deuteronomy', 1, 43, '&nbsp;مالِک خُدائ چې څۀ فرمائيلى وُو نو هغه ما تاسو ته وفرمائيل، خو تاسو هغې ته هيڅ توجو ورنۀ کړه. تاسو د هغۀ خِلاف سرکشى وکړه او د خپل غرور سره د غرونو مُلک ته روان شوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4513, 'Deuteronomy 1:44', 'Deuteronomy', 1, 44, '&nbsp;نو په هغه غرونو کښې چې کوم اموريان اوسېدل هغوئ ستاسو خِلاف لکه د مچو په شان راووتل. هغوئ د حُرمه پورې په تاسو پسې وُو او هلته يې د غرونو په مُلک ادوم کښې شکست درکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4514, 'Deuteronomy 1:45', 'Deuteronomy', 1, 45, '&nbsp;بيا تاسو د مالِک خُدائ په مخکښې وژړل، خو نۀ هغۀ ستاسو فرياد واورېدو او نۀ يې درته غوږ ونيوو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4515, 'Deuteronomy 1:46', 'Deuteronomy', 1, 46, '&nbsp;نو د هغې نه پس مونږ په قادِس کښې ډېر وخت ايسار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4516, 'Deuteronomy 2:1', 'Deuteronomy', 2, 1, '&nbsp;په آخر کښې مونږ راوګرځېدو او په هغه لار بيابان ته لاړُو کومه چې بحرِقُلزم ته تلې وه، هم هغه شان چې څنګه مالِک خُدائ حُکم کړے وو او ډېره موده د غرونو مُلک ادوم کښې سرګردانه ګرځېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4517, 'Deuteronomy 2:2', 'Deuteronomy', 2, 2, '&nbsp;بيا مالِک خُدائ ما ته وفرمائيل چې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4518, 'Deuteronomy 2:3', 'Deuteronomy', 2, 3, '&nbsp;تاسو ډېره موده په دې غرونو کښې په ګرځېدو تېره کړې ده نو د شمال طرف ته لاړ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4519, 'Deuteronomy 2:4', 'Deuteronomy', 2, 4, '&nbsp;هغۀ ما ته وفرمائيل چې دوئ ته دا اصُول وښايه، تاسو به د غرونو مُلک ادوم نه تېر شئ، چې هغه ستاسو د لرې خپلوانو د عِيسو علاقه ده. هغوئ به ستاسو نه ويريږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4520, 'Deuteronomy 2:5', 'Deuteronomy', 2, 5, '&nbsp;خو تاسو به هغوئ نۀ راپاروئ، ځکه چې زۀ تاسو له د هغوئ د مُلک يو قدم ځائ هم نۀ درکوم. ادوم ما د عِيسو اولاد له ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4521, 'Deuteronomy 2:6', 'Deuteronomy', 2, 6, '&nbsp;تاسو به خوراک او اوبۀ د هغوئ نه په پېسو اخلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4522, 'Deuteronomy 2:7', 'Deuteronomy', 2, 7, '&nbsp;ياد ساتئ چې مالِک خُدائ ستاسو خُدائ پاک څنګه تاسو له په هر کار کښې برکت درکړے دے. کله چې تاسو په دې لوئ بيابان کښې سرګردانه ګرځېدئ نو هغۀ ستاسو خيال ساتلے دے. هغه په دې څلوېښتو کالو کښې ستاسو مل وو او په تاسو باندې د يو څيز کمے هم نۀ دے راغلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4523, 'Deuteronomy 2:8', 'Deuteronomy', 2, 8, '&nbsp;نو مونږ روان وُو او هغه لار مو پرېښوده کومه چې د ايلات او عصيون‌جابر ښارونو نه د مالګې درياب ته تلې وه او مونږ د موآب صحرا په طرف تاو شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4524, 'Deuteronomy 2:9', 'Deuteronomy', 2, 9, '&nbsp;مالِک خُدائ ما ته وفرمائيل چې د موآب خلقو له تکليف مۀ ورکوئ، چې د لوط اولاد دے او نۀ چې ورسره جنګ وکړئ. ما هغوئ له د عار ښار ورکړے دے او زۀ به تاسو له د هغوئ د زمکې نه لږه هم نۀ درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4525, 'Deuteronomy 2:10', 'Deuteronomy', 2, 10, '&nbsp;د دېوانو يو طاقتور نسل چې د ايميان په نوم يادېدو هغوئ د عار په ښار کښې اوسېدل. هغوئ د عناقيانو په شان لوړ لوړ وُو، کوم چې د دېوانو بل نسل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4526, 'Deuteronomy 2:11', 'Deuteronomy', 2, 11, '&nbsp;د عناقيانو په شان هغوئ هم د رفائيانو په نوم مشهور وُو، خو موآبيانو هغوئ ته ايميان وئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4527, 'Deuteronomy 2:12', 'Deuteronomy', 2, 12, '&nbsp;حوريان په ادوم کښې اوسېدل، خو د عِيسو اولاد هغوئ وشړل، د هغوئ قوم يې تباه کړو او د هغوئ په ځائ په خپله اوسېدل، لکه څنګه چې وروستو بنى اِسرائيلو خپل دشمنان د هغه مُلک نه وشړل کوم چې مالِک خُدائ هغوئ له ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4528, 'Deuteronomy 2:13', 'Deuteronomy', 2, 13, '&nbsp;موسىٰ خپله خبره جارى وساتله او وې فرمائيل، ”بيا مونږ د زرد سيند نه پورې وتلو لکه څنګه چې مالِک خُدائ مونږ ته فرمائيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4529, 'Deuteronomy 2:14', 'Deuteronomy', 2, 14, '&nbsp;دا د هغې نه اتۀ دېرش کاله پس وُو چې مونږ د قادِس برنيع نه تلى وُو. د هغه نسل د جنګ ټول سړى مړۀ شوى وُو، لکه څنګه چې مالِک خُدائ فرمائيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4530, 'Deuteronomy 2:15', 'Deuteronomy', 2, 15, '&nbsp;مالِک خُدائ هغوئ له تر هغه سزا ورکوله چې هغوئ ټول د قوم نه ختم شوى نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4531, 'Deuteronomy 2:16', 'Deuteronomy', 2, 16, '&nbsp;کله چې جنګ ته د برابر عُمر ټول سړى مړۀ شوى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4532, 'Deuteronomy 2:17', 'Deuteronomy', 2, 17, '&nbsp;نو مالِک خُدائ مونږ ته وفرمائيل چې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4533, 'Deuteronomy 2:18', 'Deuteronomy', 2, 18, '&nbsp;نن به تاسو د عار په لاره د موآب علاقې نه تېرېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4534, 'Deuteronomy 2:19', 'Deuteronomy', 2, 19, '&nbsp;بيا به تاسو د عمونيانو مُلک ته نزدې شئ، کوم چې د لوط اولاد دے. هغوئ له تکليف مۀ ورکوئ او نۀ چې ورسره جنګ وکړئ، ځکه چې ما کومه زمکه هغوئ له ورکړې ده د هغې زمکې نه لږه هم تاسو له نۀ درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4535, 'Deuteronomy 2:20', 'Deuteronomy', 2, 20, '&nbsp;دا علاقه د رفائيانو د مُلک په نوم هم مشهور ده، دا د هغه خلقو نوم دے چې هلته اوسېدل، عمونيانو هغوئ د زمزميانو په نوم يادول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4536, 'Deuteronomy 2:21', 'Deuteronomy', 2, 21, '&nbsp;هغوئ د عناقيانو په شان لوړ لوړ وُو. هغوئ ډېر زيات وُو او هغوئ يو طاقتور نسل وو. خو مالِک خُدائ هغوئ تباه کړل، نو عمونيانو د هغوئ په مُلک قبضه وکړه او د هغوئ په ځائ په خپله اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4537, 'Deuteronomy 2:22', 'Deuteronomy', 2, 22, '&nbsp;مالِک خُدائ د ادوميانو دپاره هم دغه شان وکړل، چې د عِيسو اولاد وو او د غرونو په مُلک ادوم کښې اوسېدل. هغۀ حوريان تباه کړل، نو ادوميانو د هغوئ په زمکه قبضه وکړه او د هغوئ په ځائ په خپله اوسېدل، چرته چې تر اوسه پورې هغوئ اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4538, 'Deuteronomy 2:23', 'Deuteronomy', 2, 23, '&nbsp;د مديترانى د سمندر د غاړې سره دا مُلک په هغه خلقو آباد وو چې هغوئ د کريت د جزيرې وُو. هغوئ عويان تباه کړل، کوم چې اصلى اوسېدونکى وُو او د غزه ښار پورې د هغوئ په ټول مُلک يې قبضه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4539, 'Deuteronomy 2:24', 'Deuteronomy', 2, 24, '&nbsp;”کله چې مونږ د موآب نه تېر شوى وُو، مالِک خُدائ مونږ ته وفرمائيل، اوس، روان شئ او د ارنون سيند نه پورې وځئ. زۀ د حسبون امورى بادشاه سيحون او د هغۀ مُلک تاسو له درکوم، په هغۀ حمله وکړئ او د هغۀ مُلک قبضه کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4540, 'Deuteronomy 2:25', 'Deuteronomy', 2, 25, '&nbsp;د نن نه به د دُنيا په ټولو قومونو باندې ستاسو يره واچوم. هر څوک به ستاسو نوم اورېدو سره په لړزان کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4541, 'Deuteronomy 2:26', 'Deuteronomy', 2, 26, '&nbsp;بيا ما د قديمات د بيابان نه د حسبون بادشاه سيحون ته د صُلحې د پېش‌کش دپاره پېغام وړُونکى ورولېږل چې وئيل چې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4542, 'Deuteronomy 2:27', 'Deuteronomy', 2, 27, '&nbsp;مونږ پرېږده چې ستا د مُلک نه تېر شُو. مونږ به نېغ روان يُو او د لارې نه به اخوا دېخوا نۀ اوړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4543, 'Deuteronomy 2:28', 'Deuteronomy', 2, 28, '&nbsp;مونږ چې کوم خوراک وخورو او چې کومې اوبۀ وڅښو نو د هغې پېسې به درکړُو. مونږ صِرف ستاسو د مُلک نه تېرېدل غواړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4544, 'Deuteronomy 2:29', 'Deuteronomy', 2, 29, '&nbsp;او چې د اُردن سيند نه هغه زمکې ته پورې وځو کومه چې مالِک خُدائ زمونږ خُدائ پاک مونږ له راکوى. د عِيسو اولاد په ادوم کښې اوسيږى او موآبيان چې په عار کښې اوسيږى، هغوئ مونږ له اجازت راکړو چې د هغوئ په علاقه کښې تېر شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4545, 'Deuteronomy 2:30', 'Deuteronomy', 2, 30, '&nbsp;خو سيحون بادشاه مونږ پرې نۀ ښودو چې د هغۀ په مُلک کښې تېر شُو. مالِک خُدائ ستاسو خُدائ پاک هغه سخت طبيعته او ضدى کړے وو، نو مونږ شکست ورکړو او د هغۀ علاقه مو ونيوله، چې تر اوسه پورې زمونږ په قبضه کښې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4546, 'Deuteronomy 2:31', 'Deuteronomy', 2, 31, '&nbsp;بيا مالِک خُدائ ما ته وفرمائيل، ګوره، ما سيحون بادشاه او د هغۀ مُلک ستاسو په مخکښې کمزورے کړے دے، د هغۀ مُلک ونيسئ او قبضه يې کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4547, 'Deuteronomy 2:32', 'Deuteronomy', 2, 32, '&nbsp;سيحون د خپلو ټولو سړو سره د يهض ښار سره نزدې زمونږ سره د جنګ دپاره راووتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4548, 'Deuteronomy 2:33', 'Deuteronomy', 2, 33, '&nbsp;خو مالِک خُدائ زمونږ خُدائ پاک هغه مونږ له په لاس کښې راکړو، مونږ هغه، د هغۀ زامن او د هغۀ ټول سړى ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4549, 'Deuteronomy 2:34', 'Deuteronomy', 2, 34, '&nbsp;هم په هغه وخت مونږ ټول ښارونه ونيول او تباه مو کړل او هر يو کس، سړى، ښځې او ماشومان مو ووژل. مونږ هيڅ څوک هم ژوندے پرې نۀ ښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4550, 'Deuteronomy 2:35', 'Deuteronomy', 2, 35, '&nbsp;مونږ څاروى بوتلل او ښارونه مو لوټ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4551, 'Deuteronomy 2:36', 'Deuteronomy', 2, 36, '&nbsp;مالِک خُدائ زمونږ خُدائ پاک د عروعير نه واخله، چې د ارنون مېدان په غاړه باندې دے او کوم ښار چې د هغه مېدان په مينځ کښې دے، تر جِلعاد پورې ټول ښارونه راباندې ونيول. داسې د يو ښار دېوالونه هم نۀ وُو چې زمونږ مخه يې نيولے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4552, 'Deuteronomy 2:37', 'Deuteronomy', 2, 37, '&nbsp;خو نۀ مونږ د عمونيانو علاقې ته لاړُو، نۀ د يبوق سيند غاړې ته، نۀ د غرونو مُلک ښارونو ته او نۀ بل نزدې يو ځائ ته لاړُو چرته چې مالِک خُدائ زمونږ خُدائ پاک د تلو نه منع کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4553, 'Deuteronomy 3:1', 'Deuteronomy', 3, 1, '&nbsp;او بيا، مونږ د بسن علاقې طرف ته لاړُو او د ادرعى ښار ته نزدې د عوج بادشاه د خپل ټول لښکر سره زمونږ سره جنګ دپاره راووتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4554, 'Deuteronomy 3:2', 'Deuteronomy', 3, 2, '&nbsp;خو مالِک خُدائ ما ته وفرمائيل چې د هغۀ نه مۀ يرېږه. زۀ هغه، د هغۀ سړى او د هغۀ ټوله علاقه تاسو له درکوم. د هغۀ سره هم هغه شان کار وکړئ لکه څنګه چې مو د امورى بادشاه سيحون سره کړے وو چې هغۀ په حسبون بادشاهى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4555, 'Deuteronomy 3:3', 'Deuteronomy', 3, 3, '&nbsp;نو مالِک خُدائ د عوج بادشاه او د هغۀ خلق هم مونږ له په لاس کښې راکړل او مونږ هغوئ ټول ووژل. يو کس هم ژوندے پاتې نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4556, 'Deuteronomy 3:4', 'Deuteronomy', 3, 4, '&nbsp;هم په هغه وخت مونږ د هغۀ ټول ښارونه قبضه کړل، داسې يو ښار هم نۀ وو چې مونږ نيولے نۀ وو. مونږ ټول شپېتۀ ښارونه ونيول، د ارجوب ټوله علاقه چرته چې د بسن بادشاه عوج بادشاهى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4557, 'Deuteronomy 3:5', 'Deuteronomy', 3, 5, '&nbsp;د دې ټولو ښارونو لوړ لوړ پاخۀ دېوالونه وُو، دروازې او د دروازو بندولو دپاره يې اړامونه وُو او هلته داسې کلى هم وُو چې دېوالونه يې نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4558, 'Deuteronomy 3:6', 'Deuteronomy', 3, 6, '&nbsp;مونږ ټول ښارونه تباه کړل او ټول سړى، ښځې او ماشومان مو ووژل، هم هغه شان لکه څنګه چې مونږ د حسبون بادشاه چې نوم يې سيحون وو په ښارونو کښې کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4559, 'Deuteronomy 3:7', 'Deuteronomy', 3, 7, '&nbsp;مونږ ټول څاروى بوتلل او ښارونه مو لوټ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4560, 'Deuteronomy 3:8', 'Deuteronomy', 3, 8, '&nbsp;په هغه وخت کښې مونږ د هغه دوه امورى بادشاهانو نه د اُردن سيند نمرخاتۀ طرف ته، د ارنون سيند نه واخله د حرمون غرۀ پورې علاقه ونيوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4561, 'Deuteronomy 3:9', 'Deuteronomy', 3, 9, '&nbsp;صيدانيان د حرمون غرۀ ته سِريون نوم اخلى او اموريان ورته سنير وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4562, 'Deuteronomy 3:10', 'Deuteronomy', 3, 10, '&nbsp;مونږ د بسن بادشاه عوج ټول مُلک قبضه کړو يعنې د لوړې علاقې ښارونه، د جِلعاد او بسن علاقې، د سلکه او ادرعى ښارونو پورې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4563, 'Deuteronomy 3:11', 'Deuteronomy', 3, 11, '&nbsp;عوج بادشاه د رفائيانو آخرى پاتې کس وو. د هغۀ د ښخېدو صندوق د کاڼى نه جوړ وو، چې ديارلس فټه اوږد او دوه ګزه پلن وو. دا تر اوسه پورې د عمونيانو په ښار ربه کښې شته دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4564, 'Deuteronomy 3:12', 'Deuteronomy', 3, 12, '&nbsp;”کله چې مونږ په هغه مُلک قبضه وکړه، نو ما د ارنون سيند ته نزدې د عروعير ښار علاقه او د غرونو مُلک جِلعاد برخه، سره د دې د ښارونو د روبين او جاد قبيلو په حواله کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4565, 'Deuteronomy 3:13', 'Deuteronomy', 3, 13, '&nbsp;د جِلعاد هغه پاتې برخه او ټول بسن ما د منسى نيمې قبيلې په حواله کړو، چرته چې عوج بادشاهى کړې وه، هغه د ټول ارجوب علاقه وه.“ بسن د رفائيانو مُلک په نوم مشهور وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4566, 'Deuteronomy 3:14', 'Deuteronomy', 3, 14, '&nbsp;د منسى قبيلې يائير د ارجوب ټوله علاقه ونيوله، کوم چې بسن دے او داسې د جسور او معکه د سرحد پورې. هغۀ په دې کلو باندې خپل نوم کېښودو او دا تر اوسه پورې د يائير کلى په نوم ياديږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4567, 'Deuteronomy 3:15', 'Deuteronomy', 3, 15, '&nbsp;”د منسى قبيلې مکير ته ما جِلعاد په حواله کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4568, 'Deuteronomy 3:16', 'Deuteronomy', 3, 16, '&nbsp;او د جِلعاد نه واخله د ارنون سيند پورې علاقه ما د روبين او جاد قبيلو په حواله کړه. د هغوئ سرحد د سيند مينځ وو او د هغوئ بل سرحد د يبوق سيند وو، چې د هغې يوه برخه د عمونيانو سرحد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4569, 'Deuteronomy 3:17', 'Deuteronomy', 3, 17, '&nbsp;د هغوئ علاقه د اُردن سيند پورې خوره وه او لاندې د ګليل درياب نه واخله د مالګې درياب پورې او د پِسګه د غرۀ لمنې پورې خوره وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4570, 'Deuteronomy 3:18', 'Deuteronomy', 3, 18, '&nbsp;هم په هغه وخت، ما هغوئ ته دا اصُول وښودل، مالِک خُدائ ستاسو خُدائ پاک د اُردن نمرخاتۀ طرف ته دا مُلک د نيولو دپاره تاسو له درکړے دے. خپلو جنګى سړو له وسله ورکړئ او هغوئ د بنى اِسرائيلو د نورو قبيلو نه مخکښې د اُردن نه پورې ولېږئ، چې په هغه مُلک نيولو کښې د هغوئ مدد وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4571, 'Deuteronomy 3:19', 'Deuteronomy', 3, 19, '&nbsp;ما ته پته ده چې تاسو سره ډېر څاروى دى، نو صِرف ستاسو ښځې، بچى او څاروى به په هغه ښارونو کښې ستاسو نه پاتې شى کوم چې ما ستاسو په حواله کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4572, 'Deuteronomy 3:20', 'Deuteronomy', 3, 20, '&nbsp;هغه مُلک چې مالِک خُدائ يې بنى اِسرائيلو له ورکوى چې د اُردن نمرپرېواتۀ طرف ته دے، د هغې په نيولو کښې تر هغې پورې د بنى اِسرائيلو مدد وکړئ چې مالِک خُدائ هغوئ هلته په امن سره اوسېدو ته پرېښى نۀ وى، لکه څنګه چې هغۀ تاسو په امن کړى يئ. د هغې نه پس، تاسو واپس دې مُلک ته راتلے شئ کوم چې ما ستاسو په حواله کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4573, 'Deuteronomy 3:21', 'Deuteronomy', 3, 21, '&nbsp;بيا ما يشوَع ته دا اصُول وښودل، تا هغه هر څۀ وليدل چې مالِک خُدائ ستاسو خُدائ پاک د هغه دوه بادشاهانو يعنې سيحون او عوج سره وکړل، او چې د چا په مُلک هم حمله کوئ نو هم هغه شان به ورسره وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4574, 'Deuteronomy 3:22', 'Deuteronomy', 3, 22, '&nbsp;د هغوئ نه مۀ يرېږئ، ځکه چې مالِک خُدائ ستاسو خُدائ پاک به ستاسو دپاره جنګ وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4575, 'Deuteronomy 3:23', 'Deuteronomy', 3, 23, '&nbsp;په هغه وخت کښې ما د زړۀ د اخلاصه دا دُعا وکړه چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4576, 'Deuteronomy 3:24', 'Deuteronomy', 3, 24, '&nbsp;اے مالِکه خُدايه، ما ته پته ده چې تا صِرف خپله لوئى او طاقت خپل خِدمت کوونکى ته څرګندول شروع کړل. په آسمان او په زمکه کښې داسې خُدائ نشته چې ستا په شان لوئ لوئ کارونه وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4577, 'Deuteronomy 3:25', 'Deuteronomy', 3, 25, '&nbsp;مالِکه خُدايه، ما پرېږده چې د اُردن سيند نه پورې وځم او چې هغه زرخېزه زمکه ووينم چې په بل طرف باندې ده او چې د غرونو ښائسته مُلک او د لبنان غرونه ووينم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4578, 'Deuteronomy 3:26', 'Deuteronomy', 3, 26, '&nbsp;خو ستاسو په وجه مالِک خُدائ ما ته په قهر وو او زما سوال يې وانۀ ورېدو. او راته يې وفرمائيل، بس نور چې د دې ذِکر ونۀ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4579, 'Deuteronomy 3:27', 'Deuteronomy', 3, 27, '&nbsp;د پِسګه غرۀ سر ته لاړ شه او هر طرف ته وګوره. چې څۀ درته ښکارى نو هغه په غور سره وګوره، ځکه چې تۀ به هيڅکله هم د اُردن نه پورې نۀ وځې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4580, 'Deuteronomy 3:28', 'Deuteronomy', 3, 28, '&nbsp;د دې په ځائ يشوَع ته خپل اصُول وښايه. د هغۀ حوصله مضبوطه کړه، ځکه چې هغه به د خلقو لارښودنه کوى چې هغه مُلک قبضه کولو له ورپورې وځى کوم چې تۀ وينې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4581, 'Deuteronomy 3:29', 'Deuteronomy', 3, 29, '&nbsp;نو مونږ بيت‌فعور ښار ته مخامخ په هغه مېدان کښې پاتې شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4582, 'Deuteronomy 4:1', 'Deuteronomy', 4, 1, '&nbsp;بيا موسىٰ خلقو ته وفرمائيل، ”نو اوس به تاسو په هغه ټولو حُکمونو عمل کوئ کوم چې زۀ درته ښايم، نو تاسو به ژوندى پاتې شئ او هغه مُلک به قبضه کړئ چې مالِک خُدائ ستاسو د پلار نيکۀ خُدائ پاک يې تاسو له درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4583, 'Deuteronomy 4:2', 'Deuteronomy', 4, 2, '&nbsp;زۀ چې تاسو له کوم حُکم درکړم په هغې کښې مۀ څۀ زياتوئ او مۀ څۀ کموئ. چې ما مالِک خُدائ ستاسو خُدائ پاک کوم حُکمونه درکړى دى په هغې عمل کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4584, 'Deuteronomy 4:3', 'Deuteronomy', 4, 3, '&nbsp;تاسو په خپله وليدل چې د فعور په غرۀ کښې مالِک خُدائ څۀ وکړل. هغۀ هغوئ ټول تباه کړل چا چې د بعل عبادت کولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4585, 'Deuteronomy 4:4', 'Deuteronomy', 4, 4, '&nbsp;خو ستاسو هغه کسان چې د مالِک خُدائ ستاسو د خُدائ پاک وفادار وُو، هغوئ تر نن ورځې پورې ژوندى پاتې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4586, 'Deuteronomy 4:5', 'Deuteronomy', 4, 5, '&nbsp;ما تاسو ته هغه ټول قانون ښودلے دے، کوم چې مالِک خُدائ زما خُدائ پاک ما ته ښودلے دے چې تاسو هغه قانون په هغه مُلک کښې پوره کړئ چې د قبضه کولو دپاره ورباندې حمله کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4587, 'Deuteronomy 4:6', 'Deuteronomy', 4, 6, '&nbsp;په وفادارۍ سره په دې عمل کوئ، نو د نورو قومونو خلقو ته به پته ولګى چې تاسو څومره هوښيار خلق يئ. کله چې هغوئ د دې ټول قانون نه خبر شى، نو هغوئ به ووائى، دا عظيم قوم څومره حِکمت او پوهه لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4588, 'Deuteronomy 4:7', 'Deuteronomy', 4, 7, '&nbsp;بل داسې يو قوم هم نشته چې هغه هر څومره لوئ وى، چې د هغوئ داسې خُدائ وى چې په ضرورت کښې ورته دومره نزدې وى لکه څومره چې مالِک خُدائ زمونږ خُدائ پاک مونږ ته نزدې دے. مونږ چې کله هم د مدد دپاره هغۀ ته سوال وکړُو نو هغه زمونږ سوال قبلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4589, 'Deuteronomy 4:8', 'Deuteronomy', 4, 8, '&nbsp;بل داسې يو قوم هم نشته چې هغه هر څومره لوئ وى، چې د هغوئ سره داسې د صداقت قانون وى لکه چې نن ما تاسو ته ښودلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4590, 'Deuteronomy 4:9', 'Deuteronomy', 4, 9, '&nbsp;پام کوئ. او دا خبره يقينى کړئ چې تر کومې پورې تاسو ژوندى يئ نو څۀ چې مو په خپلو سترګو ليدلى دى هغه مۀ هېروئ. خپل بچى او نمسى د هغه ورځې نه خبر کړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4591, 'Deuteronomy 4:10', 'Deuteronomy', 4, 10, '&nbsp;چې تاسو د سينا په غرۀ باندې د مالِک خُدائ ستاسو خُدائ پاک په حضور کښې ولاړ وئ، کله چې هغۀ ما ته وفرمائيل چې، خلق راغونډ کړه. زۀ غواړم چې د هغوئ سره خبرې وکړم، نو چې تر کومې پورې هغوئ ژوندى وى نو زما فرمانبردارى به زده کوى او خپلو بچو ته به ښائى چې هم دغسې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4592, 'Deuteronomy 4:11', 'Deuteronomy', 4, 11, '&nbsp;چې تاسو څنګه د غرۀ لمنې ته لاړئ او هلته ودرېدئ په کوم چې اور لګېدلے وو او لمبې يې آسمان ته ختلې او وريځ او تکه توره تيارۀ شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4593, 'Deuteronomy 4:12', 'Deuteronomy', 4, 12, '&nbsp;هغوئ ته ووايئ چې مالِک خُدائ ستاسو سره څنګه د اور نه خبرې وکړې، تاسو څنګه د هغۀ خبرې واورېدلې خو د هغۀ صورت مو ونۀ ليدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4594, 'Deuteronomy 4:13', 'Deuteronomy', 4, 13, '&nbsp;هغۀ تاسو ته وفرمائيل چې د هغه لوظ پوره کولو دپاره به څۀ کوئ، تاسو به په هغه لسو حُکمونو عمل کوئ، کوم چې هغۀ د کاڼو په هغه دوه تختو باندې ليکلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4595, 'Deuteronomy 4:14', 'Deuteronomy', 4, 14, '&nbsp;مالِک خُدائ ما ته وفرمائيل چې تاسو ته هغه ټول قانون وښايم چې په هغې به تاسو په هغه مُلک کښې عمل کوئ چې په کوم باندې تاسو حمله کوئ او قبضه کوئ يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4596, 'Deuteronomy 4:15', 'Deuteronomy', 4, 15, '&nbsp;کله چې مالِک خُدائ د سينا په غرۀ باندې د اور نه تاسو سره خبرې وکړې او تاسو د هغۀ صورت ونۀ ليدو، نو خپلې فائدې دپاره پام کوئ چې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4597, 'Deuteronomy 4:16', 'Deuteronomy', 4, 16, '&nbsp;په هر شکل کښې بُت جوړولو په وجه خپل ځانونه ګناهګار نۀ کړئ، کۀ هغه شکل د نر وى، يا د ښځې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4598, 'Deuteronomy 4:17', 'Deuteronomy', 4, 17, '&nbsp;د ځناور يا د مارغۀ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4599, 'Deuteronomy 4:18', 'Deuteronomy', 4, 18, '&nbsp;د داسې يو ځناور چې په زمکه تلل کوى يا کۀ په اوبو کښې د کب وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4600, 'Deuteronomy 4:19', 'Deuteronomy', 4, 19, '&nbsp;په داسې آزمېښت کښې مۀ پرېوځئ چې څۀ په آسمان کښې ګورئ چې د هغې عبادت يا خِدمت وکړئ، لکه نمر، سپوږمۍ او ستورى. مالِک خُدائ ستاسو خُدائ پاک نورو ټولو خلقو ته دا ورکړى دى چې عبادت يې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');